      hold_id TEXT NOT NULL REFERENCES holds(id) ON DELETE CASCADE,
      seat_id TEXT NOT NULL REFERENCES seats(id) ON DELETE CASCADE,
      PRIMARY KEY (hold_id, seat_id)
    );
