  const count = await db.query('SELECT COUNT(*)::int AS count FROM seats');
  if (Number(count.rows[0].count) === 0) {
    await tx(async () => {
      for (const row of ROWS) {
        for (let seat = 1; seat <= SEATS_PER_ROW; seat += 1) {
          const id = `${row}-${seat}`;
          await db.query(
