  }

  async run(fn) {
    const previous = this._tail;
    let release;
    this._tail = new Promise((resolve) => {
      release = resolve;
    });
    await previous;
    try {
      return await fn();
    } finally {
      release();
    }
  }
}

const writeMutex = new Mutex();

function placeholders(count, offset = 1) {
  return Array.from({ length: count }, (_, i) => `$${i + offset}`).join(', ');
}

