  constructor() {
    this._tail = Promise.resolve();
  }

  async run(fn) {
    const previous = this._tail;
    let release;
    this._tail = new Promise((resolve) => {
      release = resolve;
    });
    await previous;
    try {
      return await fn();
    } finally {
