.seat.booked { background: #e2e8f0; color: #475569; cursor: not-allowed; text-decoration: line-through; }
.seat.selected { background: #2563eb; color: white; border-color: #93c5fd; }
.seat.mine { outline: 3px solid #f59e0b; }
.seat.conflict { animation: pulse .8s ease-in-out 3; outline: 3px solid #ef4444; }

.legend { display: flex; flex-wrap: wrap; gap: 14px; margin-top: 20px; color: #475569; font-weight: 700; }
.legend span { display: inline-flex; align-items: center; gap: 6px; }
.legend i { width: 14px; height: 14px; display: inline-block; border-radius: 4px; }
.legend .available { background: #86efac; }
.legend .held { background: #fde68a; }
.legend .booked { background: #cbd5e1; }
.legend .selected { background: #2563eb; }

@keyframes pulse {
  50% { transform: scale(1.08); }
}

@media (max-width: 720px) {
  .hero, .controls { align-items: stretch; flex-direction: column; }
  .stats { grid-template-columns: repeat(2, 1fr); }
  .stage { padding: 12px; }
  .seatRow { grid-template-columns: repeat(5, 1fr); }
}
