let c2=await req(`/api/holds/${hid}/confirm`,{method:'POST',body:JSON.stringify({sessionId:sid})}); assert(c2.status===200 && c2.body.idempotent,'idempotent confirm');
let h=await req('/api/holds',{method:'POST',body:JSON.stringify({seatIds:['C-2','C-3'],sessionId:'ttl'})}); assert(h.status===201,'ttl hold');
let blocked=await req('/api/holds',{method:'POST',body:JSON.stringify({seatIds:['C-2'],sessionId:'blocked'})}); assert(blocked.status===409 && blocked.body.conflicts[0]==='C-2','active hold blocks');
await new Promise(r=>setTimeout(r,2500));
