* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; }
button { font: inherit; }

.shell {
  width: min(1100px, calc(100vw - 32px));
  margin: 0 auto;
  padding: 32px 0;
}

.hero {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: center;
  margin-bottom: 16px;
}

h1 { margin: 0; font-size: clamp(2rem, 5vw, 4rem); line-height: 1; }
.eyebrow { margin: 0 0 8px; text-transform: uppercase; letter-spacing: .16em; color: #52627a; font-weight: 800; }
.subtle { margin: 10px 0 0; color: #52627a; }
code { background: #dbe4f0; border-radius: 6px; padding: 2px 6px; }

.panel {
  background: rgba(255,255,255,.86);
  border: 1px solid #d9e2ef;
  border-radius: 22px;
  box-shadow: 0 20px 50px rgba(31, 45, 71, .08);
}

.connection {
  padding: 8px 14px;
  border-radius: 999px;
  font-weight: 800;
}
.connection.ok { color: #075e35; background: #d8f8e6; }
.connection.bad { color: #8a3a00; background: #ffe7c2; }

.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  overflow: hidden;
  margin: 18px 0;
}
.stats div { padding: 18px; background: white; }
.stats strong { display: block; font-size: 2rem; }
.stats span { color: #52627a; }

.controls {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: center;
  padding: 16px;
  margin-bottom: 14px;
}
.controls > div:first-child { display: flex; flex-wrap: wrap; gap: 8px; }
.controls button {
  border: 0;
  border-radius: 12px;
  padding: 10px 14px;
  background: #1d4ed8;
  color: white;
  cursor: pointer;
  font-weight: 800;
}
.controls button:disabled { opacity: .45; cursor: not-allowed; }
#releaseBtn { background: #b45309; }
#refreshBtn { background: #475569; }
.holdInfo { color: #334155; }

.message {
  min-height: 24px;
  margin: 10px 0;
  font-weight: 700;
}
.message.success { color: #047857; }
.message.warn { color: #b45309; }
.message.error { color: #b91c1c; }

.stage { padding: 22px; }
.screen {
  width: min(520px, 80%);
  margin: 0 auto 26px;
  padding: 12px;
  text-align: center;
  color: #64748b;
  background: linear-gradient(90deg, transparent, #cbd5e1, transparent);
  border-radius: 50% 50% 8px 8px;
  font-weight: 900;
  letter-spacing: .25em;
}
.row { display: grid; grid-template-columns: 32px 1fr; align-items: center; gap: 12px; margin: 10px 0; }
.rowLabel { color: #64748b; font-weight: 900; text-align: center; }
.seatRow { display: grid; grid-template-columns: repeat(10, minmax(32px, 1fr)); gap: 8px; }

.seat {
  aspect-ratio: 1;
  border: 2px solid transparent;
  border-radius: 12px 12px 18px 18px;
  cursor: pointer;
  font-weight: 900;
  transition: transform .12s ease, box-shadow .12s ease;
}
.seat:not(:disabled):hover { transform: translateY(-2px); box-shadow: 0 8px 18px rgba(30, 64, 175, .18); }
.seat.available { background: #dcfce7; color: #166534; }
.seat.held { background: #fef3c7; color: #92400e; cursor: not-allowed; }
.seat.booked { background: #e2e8f0; color: #475569; cursor: not-allowed; text-decoration: line-through; }
.seat.selected { background: #2563eb; color: white; border-color: #93c5fd; }
.seat.mine { outline: 3px solid #f59e0b; }
.seat.conflict { animation: pulse .8s ease-in-out 3; outline: 3px solid #ef4444; }

.legend { display: flex; flex-wrap: wrap; gap: 14px; margin-top: 20px; color: #475569; font-weight: 700; }
.legend span { display: inline-flex; align-items: center; gap: 6px; }
.legend i { width: 14px; height: 14px; display: inline-block; border-radius: 4px; }
.legend .available { background: #86efac; }
.legend .held { background: #fde68a; }
.legend .booked { background: #cbd5e1; }
.legend .selected { background: #2563eb; }

@keyframes pulse {
  50% { transform: scale(1.08); }
}

@media (max-width: 720px) {
  .hero, .controls { align-items: stretch; flex-direction: column; }
  .stats { grid-template-columns: repeat(2, 1fr); }
  .stage { padding: 12px; }
  .seatRow { grid-template-columns: repeat(5, 1fr); }
}
"}

