{"command": "node --input-type=module - <<'NODE'
const base='http://localhost:3000';
async function req(path, opts){ const r=await fetch(base+path,{headers:{'content-type':'application/json'},...opts}); let j; try{j=await r.json()}catch{j=null}; return {status:r.status, body:j};}
function assert(cond,msg){ if(!cond) throw new Error(msg); }
let s=await req('/api/seats'); assert(s.status===200,'seats status'); assert(s.body.inventory.total===50,'total'); assert(s.body.inventory.available+s.body.inventory.held+s.body.inventory.booked===50,'reconcile');
let results=await Promise.all(Array.from({length:20},(_,i)=>req('/api/holds',{method:'POST',body:JSON.stringify({seatIds:['C-1'],sessionId:'c'+i})})));
assert(results.filter(r=>r.status===201).length===1,'exactly one concurrent success'); assert(results.filter(r=>r.status===409).length===19,'losers conflict');
let win=results.find(r=>r.status===201); let sid=win.body.hold.sessionId; let hid=win.body.hold.id;
let c1=await req(`/api/holds/${hid}/confirm`,{method:'POST',body:JSON.stringify({sessionId:sid})}); assert(c1.status===200 && !c1.body.idempotent,'confirm');
let c2=await req(`/api/holds/${hid}/confirm`,{method:'POST',body:JSON.stringify({sessionId:sid})}); assert(c2.status===200 && c2.body.idempotent,'idempotent confirm');
let h=await req('/api/holds',{method:'POST',body:JSON.stringify({seatIds:['C-2','C-3'],sessionId:'ttl'})}); assert(h.status===201,'ttl hold');
let blocked=await req('/api/holds',{method:'POST',body:JSON.stringify({seatIds:['C-2'],sessionId:'blocked'})}); assert(blocked.status===409 && blocked.body.conflicts[0]==='C-2','active hold blocks');
await new Promise(r=>setTimeout(r,2500));
let exp=await req(`/api/holds/${h.body.hold.id}/confirm`,{method:'POST',body:JSON.stringify({sessionId:'ttl'})}); assert(exp.status===409,'expired confirm fails');
s=await req('/api/seats'); assert(s.body.inventory.available+s.body.inventory.held+s.body.inventory.booked===50,'final reconcile'); assert(s.body.seats.find(x=>x.id==='C-2').status==='available','expired seat available');
console.log('verification ok', s.body.inventory);
NODE", "duration": 20}

